#!/bin/bash
source ./laghos_env.sh

pushd $ZLIB_ROOT
rm -rf $ZLIB_INSTALL_DIR 
mkdir $ZLIB_INSTALL_DIR
make clean
CC=$CC ./configure --prefix=$ZLIB_INSTALL_DIR --static
make -j
make install -j
popd

rm -rf $METIS_BUILD_DIR $METIS_INSTALL_DIR 
mkdir $METIS_BUILD_DIR $METIS_INSTALL_DIR
pushd $METIS_BUILD_DIR
cmake .. -DCMAKE_C_COMPILER=$CC -DCMAKE_INSTALL_PREFIX=$METIS_INSTALL_DIR -DCMAKE_BUILD_TYPE=Release -DCMAKE_VERBOSE_MAKEFILE=ON -DCMAKE_INTERPROCEDURAL_OPTIMIZATION=OFF -DCMAKE_POLICY_DEFAULT_CMP0090=NEW -DCMAKE_FIND_USE_PACKAGE_REGISTRY=OFF -DCMAKE_EXPORT_COMPILE_COMMANDS=ON -DSHARED=ON -DGDB=OFF -DGKLIB_PATH=../GKlib
make clean
make -j
make install -j
popd

rm -rf $ADIAK_BUILD_DIR $ADIAK_INSTALL_DIR 
mkdir $ADIAK_BUILD_DIR $ADIAK_INSTALL_DIR
pushd $ADIAK_BUILD_DIR
cmake .. -DCMAKE_C_COMPILER=$CC -DCMAKE_CXX_COMPILER=$CXX -DMPI_CXX_COMPILER=$MPICXX -DMPI_C_COMPILER=$MPICC -DCMAKE_PREFIX_PATH="$CC_DIR;$MPI_DIR" -DCMAKE_INSTALL_PREFIX=$ADIAK_INSTALL_DIR -DCMAKE_BUILD_TYPE=Release -DCMAKE_VERBOSE_MAKEFILE=ON -DCMAKE_INTERPROCEDURAL_OPTIMIZATION=OFF -DCMAKE_POLICY_DEFAULT_CMP0090=NEW -DCMAKE_FIND_USE_PACKAGE_REGISTRY=OFF -DCMAKE_EXPORT_COMPILE_COMMANDS=ON -DENABLE_MPI=ON -DBUILD_SHARED_LIBS=OFF -DENABLE_TESTS=OFF
make clean
make -j
make -j install
popd

rm -rf $CALIPER_BUILD_DIR $CALIPER_INSTALL_DIR 
mkdir $CALIPER_BUILD_DIR $CALIPER_INSTALL_DIR 
pushd $CALIPER_BUILD_DIR
cmake .. -DCMAKE_C_COMPILER=$CC -DCMAKE_CXX_COMPILER=$CXX -DMPI_CXX_COMPILER=$MPICXX -DMPI_C_COMPILER=$MPICC -DCMAKE_C_FLAGS="-g -O2" -DCMAKE_CXX_FLAGS="-g -O2 -std=c++14" -DCMAKE_EXE_LINKER_FLAGS="-ldl" -DCMAKE_MODULE_LINKER_FLAGS="-ldl" -DCMAKE_SHARED_LINKER_FLAGS="-ldl" -DCMAKE_PREFIX_PATH="$CC_DIR;$MPI_DIR;$ROCM_PATH;$PYTHON_PATH;$ADIAK_INSTALL_DIR" -DCMAKE_INSTALL_PREFIX=$CALIPER_INSTALL_DIR -DCMAKE_BUILD_TYPE=Release -DCMAKE_VERBOSE_MAKEFILE=ON -DCMAKE_INTERPROCEDURAL_OPTIMIZATION=OFF -DCMAKE_POLICY_DEFAULT_CMP0090=NEW -DCMAKE_FIND_USE_PACKAGE_REGISTRY=OFF -DCMAKE_EXPORT_COMPILE_COMMANDS=ON -DPython_EXECUTABLE=$PYTHON_DIR/bin/python3.9 -DWITH_FORTRAN=OFF -DBUILD_SHARED_LIBS=ON -DBUILD_TESTING=OFF -DWITH_TOOLS=ON -DBUILD_DOCS=OFF -DWITH_MPI=ON -DROCM_PATH=$ROCM_PATH -DCMAKE_HIP_ARCHITECTURES=$ROCM_ARCH -DWITH_CUPTI=OFF -DWITH_NVTX=OFF -DWITH_ROCTRACER=ON -DWITH_ROCTX=ON -Dadiak_DIR=$ADIAK_INSTALL_DIR -DWITH_ADIAK=ON -DWITH_GOTCHA=ON -DWITH_SAMPLER=ON -DWITH_PAPI=OFF -DWITH_LIBDW=OFF -DWITH_LIBPFM=OFF -DWITH_KOKKOS=ON -DWITH_VARIORUM=OFF -DWITH_VTUNE=OFF -DWITH_PYTHON_BINDINGS=OFF -DWITH_LIBUNWIND=OFF
make clean
make -j
make -j install
popd

rm -rf $FMT_BUILD_DIR $FMT_INSTALL_DIR 
mkdir $FMT_BUILD_DIR $FMT_INSTALL_DIR 
pushd $FMT_BUILD_DIR
cmake .. -DCMAKE_C_COMPILER=$CC -DCMAKE_CXX_COMPILER=$CXX -DMPI_CXX_COMPILER=$MPICXX -DMPI_C_COMPILER=$MPICC -DCMAKE_INSTALL_PREFIX=$FMT_INSTALL_DIR -DCMAKE_PREFIX_PATH=$CC_ROOT -DCMAKE_BUILD_TYPE=Release -DCMAKE_VERBOSE_MAKEFILE=ON -DCMAKE_INTERPROCEDURAL_OPTIMIZATION=OFF -DCMAKE_POLICY_DEFAULT_CMP0090=NEW -DCMAKE_FIND_USE_PACKAGE_REGISTRY=OFF -DCMAKE_EXPORT_COMPILE_COMMANDS=ON -DCMAKE_POSITION_INDEPENDENT_CODE=ON -DCMAKE_CXX_STANDARD=11 -DCMAKE_CXX_STANDARD_REQUIRED=ON -DFMT_DOC=OFF -DFMT_TEST=OFF
make clean
make -j
make -j install
popd

rm -rf $CAMP_BUILD_DIR $CAMP_INSTALL_DIR 
mkdir $CAMP_BUILD_DIR $CAMP_INSTALL_DIR 
pushd $CAMP_BUILD_DIR
cmake .. -DCMAKE_C_COMPILER=$CC -DCMAKE_CXX_COMPILER=$CXX -DMPI_CXX_COMPILER=$MPICXX -DMPI_C_COMPILER=$MPICC -DCMAKE_C_FLAGS="-Wall -Wextra -g -O2 -pthread" -DCMAKE_CXX_FLAGS="-Wall -Wextra -g -O2 -std=c++14 -pthread" -DCMAKE_INSTALL_PREFIX=$CAMP_INSTALL_DIR -DCMAKE_PREFIX_PATH="$CC_DIR;$MPI_DIR;$ROCM_PATH;$ROCM_PATH/llvm" -DCMAKE_BUILD_TYPE=Release -DCMAKE_VERBOSE_MAKEFILE=ON -DCMAKE_INTERPROCEDURAL_OPTIMIZATION=OFF -DCMAKE_POLICY_DEFAULT_CMP0090=NEW -DCMAKE_FIND_USE_PACKAGE_REGISTRY=OFF -DCMAKE_EXPORT_COMPILE_COMMANDS=ON -DENABLE_CUDA=OFF -DENABLE_HIP=ON -DHIP_ROOT_DIR=$ROCM_PATH -DCMAKE_HIP_ARCHITECTURES=$ROCM_ARCH -DGPU_TARGETS=$ROCM_ARCH -DAMDGPU_TARGETS=$ROCM_ARCH -DENABLE_TESTS=OFF -DENABLE_OPENMP=OFF -DCAMP_ENABLE_TARGET_OPENMP=OFF -DENABLE_SYCL=OFF -DENABLE_MPI=ON
make clean
make -j
make -j install
popd

rm -rf $UMPIRE_BUILD_DIR $UMPIRE_INSTALL_DIR 
mkdir $UMPIRE_BUILD_DIR $UMPIRE_INSTALL_DIR 
pushd $UMPIRE_BUILD_DIR
cmake .. -DCMAKE_C_COMPILER=$CC -DCMAKE_CXX_COMPILER=$CXX -DMPI_CXX_COMPILER=$MPICXX -DMPI_C_COMPILER=$MPICC -DCMAKE_C_FLAGS="-g -O2" -DCMAKE_CXX_FLAGS="-g -O2 -std=c++14" -DCMAKE_EXE_LINKER_FLAGS="-ldl" -DCMAKE_MODULE_LINKER_FLAGS="-ldl" -DCMAKE_SHARED_LINKER_FLAGS="-ldl" -DCMAKE_INSTALL_PREFIX=$UMPIRE_INSTALL_DIR -DCMAKE_PREFIX_PATH="$CAMP_INSTALL_DIR;$FMT_INSTALL_DIR;$CC_ROOT;$ROCM_PATH;$ROCM_PATH/llvm;$MPI_DIR" -DCMAKE_BUILD_TYPE=Release -DCMAKE_VERBOSE_MAKEFILE=ON -DCMAKE_INTERPROCEDURAL_OPTIMIZATION=OFF -DCMAKE_POLICY_DEFAULT_CMP0090=NEW -DCMAKE_FIND_USE_PACKAGE_REGISTRY=OFF -DCMAKE_EXPORT_COMPILE_COMMANDS=ON -DENABLE_FORTRAN=OFF -DUMPIRE_ENABLE_C=ON -DENABLE_MPI=ON -DUMPIRE_ENABLE_MPI3_SHARED_MEMORY=OFF -DROCM_PATH=$ROCM_PATH -DCMAKE_HIP_ARCHITECTURES=$ROCM_ARCH -DENABLE_CUDA=OFF -DENABLE_HIP=ON -DUMPIRE_ENABLE_DEVICE_CONST=OFF -DUMPIRE_ENABLE_OPENMP_TARGET=OFF -Dcamp_DIR=$CAMP_INSTALL_DIR -Dfmt_DIR=$FMT_INSTALL_DIR -DBUILD_SHARED_LIBS=ON -DENABLE_WARNINGS_AS_ERRORS=OFF -DENABLE_OPENMP=OFF -DENABLE_EXAMPLES=OFF -DENABLE_DOCS=OFF -DENABLE_BENCHMARKS=OFF -DENABLE_TESTS=OFF -DUMPIRE_ENABLE_NUMA=OFF -DUMPIRE_ENABLE_DEVELOPER_BENCHMARKS=OFF -DUMPIRE_ENABLE_TOOLS=OFF -DUMPIRE_ENABLE_BACKTRACE=OFF -DUMPIRE_ENABLE_ASAN=OFF -DUMPIRE_ENABLE_SANITIZER_TESTS=OFF -DUMPIRE_ENABLE_DEVICE_ALLOCATOR=OFF -DUMPIRE_ENABLE_SQLITE_EXPERIMENTAL=OFF -DUMPIRE_ENABLE_IPC_SHARED_MEMORY=OFF
make clean
make -j
make -j install
popd

rm -rf $HYPRE_INSTALL_DIR 
mkdir $HYPRE_INSTALL_DIR 
pushd $HYPRE_ROOT
cd src
make clean
CC=$MPICC CXX=$MPICXX CFLAGS="-g -O2" CXXFLAGS="-g -O2 -std=c++14" ./configure --prefix=$HYPRE_INSTALL_DIR --with-lapack --with-blas --with-lapack-libs=$BLAS_LAPACK_LIBS --with-blas-libs=$BLAS_LAPACK_LIBS --with-lapack-lib-dirs=$BLAS_LAPACK_LIB_DIRS --with-blas-lib-dirs=$BLAS_LAPACK_LIB_DIRS --with-MPI --with-MPI-lib-dirs="$MPI_LIB_DIRS" --with-MPI-libs="$MPI_LIBS" --with-MPI-include=$MPI_DIR/include --without-openmp --disable-bigint --enable-mixedint --disable-complex --enable-shared --without-superlu --without-mli --with-umpire --with-umpire-include=$UMPIRE_INSTALL_DIR/include --with-umpire-lib=$UMPIRE_INSTALL_DIR/lib64/libumpire.so --with-caliper --with-caliper-include=$CALIPER_INSTALL_DIR/include --with-caliper-lib=$CALIPER_INSTALL_DIR/lib64/libcaliper.so --disable-debug --without-cuda --disable-curand --disable-cusparse --disable-cusolver --with-hip --enable-rocblas --enable-rocsolver --enable-rocrand --enable-rocsparse --with-extra-CUFLAGS=-I$ROCM_PATH/include --with-gpu-arch=$ROCM_ARCH --disable-fortran --enable-gpu-aware-mpi
make -j
make -j install
popd

rm -rf $MFEM_INSTALL_DIR 
mkdir $MFEM_INSTALL_DIR 
pushd $MFEM_ROOT
make clean
make -j1 config PREFIX=$MFEM_INSTALL_DIR MFEM_USE_MEMALLOC=YES MFEM_DEBUG=NO CXX=$CXX CXXFLAGS="-g -O2 -std=c++17" MPICXX=$MPICXX MFEM_USE_LIBUNWIND=NO MFEM_USE_ZLIB=YES MFEM_USE_METIS=YES MFEM_USE_METIS_5=YES MFEM_THREAD_SAFE=NO MFEM_USE_MPI=YES MFEM_USE_LAPACK=NO MFEM_USE_SUPERLU=NO MFEM_USE_STRUMPACK=NO MFEM_USE_SUITESPARSE=NO MFEM_USE_SUNDIALS=NO MFEM_USE_PETSC=NO MFEM_USE_SLEPC=NO MFEM_USE_PUMI=NO MFEM_USE_GSLIB=NO MFEM_USE_NETCDF=NO MFEM_USE_MPFR=NO MFEM_USE_GNUTLS=NO MFEM_USE_OPENMP=NO MFEM_USE_CONDUIT=NO MFEM_USE_CUDA=NO MFEM_USE_HIP=YES MFEM_USE_OCCA=NO MFEM_USE_RAJA=NO MFEM_USE_AMGX=NO MFEM_USE_CEED=NO MFEM_USE_UMPIRE=YES MFEM_USE_FMS=NO MFEM_USE_GINKGO=NO MFEM_USE_HIOP=NO MFEM_USE_ENZYME=NO MFEM_MPIEXEC=mpirun MFEM_MPIEXEC_NP=-np MFEM_USE_EXCEPTIONS=NO MFEM_USE_MUMPS=NO MFEM_PRECISION=double HYPRE_OPT=-I$HYPRE_INSTALL_DIR/include HYPRE_LIB="-Wl,-rpath,$HYPRE_INSTALL_DIR/lib -Wl,-rpath,$BLAS_LAPACK_LIB_DIRS -L$HYPRE_INSTALL_DIR/lib -L$BLAS_LAPACK_LIB_DIRS -lHYPRE $BLAS_LAPACK_LIBS_FLAGS -Wl,-rpath,$ROCM_PATH/lib -L$ROCM_PATH/lib -lrocsparse -lrocrand" METIS_OPT=-I$METIS_INSTALL_DIR/include METIS_LIB="-Wl,-rpath,$METIS_INSTALL_DIR/lib -L$METIS_INSTALL_DIR/lib -lmetis" ZLIB_OPT=-I$ZLIB_INSTALL_DIR/include ZLIB_LIB="-Wl,-rpath,$ZLIB_INSTALL_DIR/lib -L$ZLIB_INSTALL_DIR/lib -lz" HIP_CXX=$HIPCC HIP_ARCH=$ROCM_ARCH HIP_DIR=$ROCM_PATH HIP_OPT=-I$ROCM_PATH/include HIP_LIB="-Wl,-rpath,$ROCM_PATH/lib -Wl,-rpath,$CC_DIR/cce/x86_64/lib -Wl,-rpath,$CC_DIR/cce-clang/x86_64/lib -Wl,-rpath,$CRAYPE_DIR/lib64 -L$ROCM_PATH/lib -L$CC_DIR/cce/x86_64/lib -L$CC_DIR/cce-clang/x86_64/lib -L$CRAYPE_DIR/lib64 -lhipsparse -lhipblas -lmodules -lfi -lcraymath -lf -lu -lcsup -lpgas-shmem -lunwind -lpmi" UMPIRE_OPT="-I$UMPIRE_INSTALL_DIR/include -I$CAMP_INSTALL_DIR/include -I$FMT_INSTALL_DIR/include" UMPIRE_LIB="-Wl,-rpath,$UMPIRE_INSTALL_DIR/lib64 -Wl,-rpath,$FMT_INSTALL_DIR/lib64 -L$UMPIRE_INSTALL_DIR/lib64 -L$FMT_INSTALL_DIR/lib64 -lumpire -lfmt" MFEM_USE_CALIPER=YES CALIPER_OPT="-I$CALIPER_INSTALL_DIR/include" CALIPER_LIB="-Wl,-rpath,$CALIPER_INSTALL_DIR/lib64 -L$CALIPER_INSTALL_DIR/lib64 -lcaliper" MFEM_USE_ADIAK=YES ADIAK_OPT="-I$ADIAK_INSTALL_DIR/include" ADIAK_LIB="-Wl,-rpath,$ADIAK_INSTALL_DIR/lib -L$ADIAK_INSTALL_DIR/lib64 -ladiak"
make -j
make -j lib
make -j install
popd

pushd $LAGHOS_ROOT
make clean
make -j16 CXX=$HIPCC CXXFLAGS="-g -O2 -std=c++17" MPICXX=$MPICXX MFEM_DIR=$MFEM_INSTALL_DIR CONFIG_MK=$MFEM_INSTALL_DIR/share/mfem/config.mk TEST_MK=$MFEM_INSTALL_DIR/share/mfem/test.mk CALIPER_DIR=$CALIPER_INSTALL_DIR ADIAK_DIR=$ADIAK_INSTALL_DIR
make install
popd
